if name == "et":
    # 端点切换预约审计业务时间快照查询（只读）：支持两种严格形态。
    # 离散形态键序 op,times：times 为 1..64 项数组，每项为 0..10^9 的
    # 非 bool 整数且严格递增、不重复。
    # 连续闭区间形态键序 op,first,last（键须按此序出现，乱序报
    # INPUT）：first、last 为 0..10^9 的非 bool 整数且 first<=last，共
    # 同给出业务时间闭区间 [first,last]。
    # 两形态均不接受 now、不推进显式时钟。字段集合、键序、UTF-8 编
    # 码、容器、数量、整数类型（排除 bool）、范围或递增/区间关系非法
    # 统一判 INPUT；任一查询时刻晚于操作开始时的全局逻辑时钟留执行期
    # 判 STATE（INPUT 判定先于状态）。
    if list(raw_op) == ["op", "times"]:
        times = raw_op["times"]
        if not isinstance(times, list) or not 1 <= len(times) <= 64:
            fail(EXIT_INPUT, "INPUT")
        previous_time = -1
        normalized_times = []
        for tm in times:
            if (
                not isinstance(tm, int)
                or isinstance(tm, bool)
                or not 0 <= tm <= 10 ** 9
            ):
                fail(EXIT_INPUT, "INPUT")
            # 严格递增即同时排除重复（相等）与乱序（倒退）。
            if tm <= previous_time:
                fail(EXIT_INPUT, "INPUT")
            previous_time = tm
            normalized_times.append(tm)
        return ("et", "points", tuple(normalized_times))
    if list(raw_op) == ["op", "first", "last"]:
        first = raw_op["first"]
        if (
            not isinstance(first, int)
            or isinstance(first, bool)
            or not 0 <= first <= 10 ** 9
        ):
            fail(EXIT_INPUT, "INPUT")
        last = raw_op["last"]
        if (
            not isinstance(last, int)
            or isinstance(last, bool)
            or not 0 <= last <= 10 ** 9
        ):
            fail(EXIT_INPUT, "INPUT")
        if first > last:
            fail(EXIT_INPUT, "INPUT")
        return ("et", "range", first, last)
    fail(EXIT_INPUT, "INPUT")

if name == "etg":
    # 端点切换预约审计业务时间区间三态与预约身份占用汇总（只读）：精确
    # 键序 op,first,last（键须按此序出现，乱序报 INPUT）。first、last
    # 为 0..10^9 的非 bool 整数且 first<=last，共同给出业务时间闭区
    # 间 [first,last]。不接受 now、不推进显式时钟。字段集合、键序、
    # UTF-8 编码、整数类型（排除 bool）、范围或区间关系非法统一判
    # INPUT；last 晚于操作开始时的全局逻辑时钟留执行期判 STATE
    # （INPUT 判定先于状态）。
    if list(raw_op) != ["op", "first", "last"]:
        fail(EXIT_INPUT, "INPUT")
    first = raw_op["first"]
    if (
        not isinstance(first, int)
        or isinstance(first, bool)
        or not 0 <= first <= 10 ** 9
    ):
        fail(EXIT_INPUT, "INPUT")
    last = raw_op["last"]
    if (
        not isinstance(last, int)
        or isinstance(last, bool)
        or not 0 <= last <= 10 ** 9
    ):
        fail(EXIT_INPUT, "INPUT")
    if first > last:
        fail(EXIT_INPUT, "INPUT")
    return ("etg", first, last)

if name == "eti":
    # 端点切换预约审计业务时间单身份占用区段查询（只读）：精确键序
    # op,digest,at,first,last（键须按此序出现，乱序报 INPUT）。digest
    # 为小写 64 位十六进制 SHA-256，digest 与 at 共同标识预约；at、
    # first、last 为 0..10^9 的非 bool 整数且 first<=last，共同给出业
    # 务时间闭区间 [first,last]。不接受 now、不推进显式时钟。字段集
